def fill_from_lines(desc,n=16,m=16):
    out=set()
    for i,(d1,l1,h1) in enumerate(desc):
      for d2,l2,h2 in desc[i+1:]:
        vlo=max(l1,l2); vhi=min(h1,h2)
        if vlo>vhi: continue
        for r in range(n):
          for c in range(m):
            d=c-r; v=c+r
            if min(d1,d2)<d<max(d1,d2) and vlo<=v<=vhi:
              out.add((r,c))
    return out
