def fill_from_lines_parity(desc,n=16,m=16):
    out=set()
    for i,(d1,l1,h1) in enumerate(desc):
      for d2,l2,h2 in desc[i+1:]:
        if (d1-l1)%2 != (d2-l2)%2: # actually v parity equals d parity
            continue
        vlo=max(l1,l2); vhi=min(h1,h2)
        # snap v endpoints to shared parity
        p=d1%2
        if vlo%2!=p: vlo+=1
        if vhi%2!=p: vhi-=1
        if vlo>vhi: continue
        for r in range(n):
          for c in range(m):
            d=c-r; v=c+r
            if min(d1,d2)<d<max(d1,d2) and vlo<=v<=vhi:
              out.add((r,c))
    return out
