def fill_adjacent(desc,n=16,m=16):
    desc=sorted(desc,key=lambda x:x[0])
    out=set()
    for (d1,l1,h1),(d2,l2,h2) in zip(desc,desc[1:]):
      vlo=max(l1,l2); vhi=min(h1,h2)
      if vlo>vhi: continue
      for r in range(n):
        for c in range(m):
          d=c-r; v=c+r
          if d1<d<d2 and vlo<=v<=vhi: out.add((r,c))
    return out
